import sys
import zipfile
import xml.etree.ElementTree as ET

def read_docx(file_path):
    try:
        with zipfile.ZipFile(file_path) as z:
            xml_content = z.read('word/document.xml')
            root = ET.fromstring(xml_content)

            # Namespace map for wordprocessingml
            namespaces = {
                'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
            }

            # Find all paragraph elements
            paragraphs = []
            for p in root.findall('.//w:p', namespaces):
                texts = []
                for t in p.findall('.//w:t', namespaces):
                    if t.text:
                        texts.append(t.text)
                if texts:
                    paragraphs.append(''.join(texts))
            return '\n'.join(paragraphs)
    except Exception as e:
        return f"Error reading docx: {e}"

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python read_docx.py <path_to_docx>")
    else:
        print(read_docx(sys.argv[1]))

export type LocalHookPoint =
  | "pre:connect"
  | "post:connect"
  | "pre:initialize"
  | "post:initialize"
  | "pre:authenticate"
  | "post:authenticate"
  | "pre:session:create"
  | "post:session:create"
  | "pre:prompt"
  | "post:prompt"
  | "pre:disconnect"
  | "post:disconnect";

export type RfcHookPoint =
  // agent.*
  | "agent.pre_tool_use"
  | "agent.post_tool_use"
  | "agent.post_tool_use_fail"
  | "agent.message_send"
  | "agent.message_recv"
  | "agent.checkpoint"
  | "agent.session_start"
  | "agent.session_end"
  | "agent.subagent_spawn"
  | "agent.experience_extracted"
  | "agent.skill_promoted"
  | "agent.respawn"
  | "agent.respawned"
  // task.*
  | "task.created"
  | "task.claimed"
  | "task.started"
  | "task.progress"
  | "task.completed"
  | "task.failed"
  | "task.escalated"
  | "task.delegated"
  | "task.before_merge"
  | "task.resume_requested"
  // council.*
  | "council.started"
  | "council.context_packaged"
  | "council.profile_snapshot_saved"
  | "council.extraction_completed"
  | "council.proposal"
  | "council.proposal_deadline"
  | "council.review"
  | "council.diff_ready"
  | "council.review_round_end"
  | "council.decision"
  | "council.completed"
  // lifecycle.*
  | "lifecycle.project_open"
  | "lifecycle.build_start"
  | "lifecycle.build_end"
  | "lifecycle.human_gate"
  // system.*
  | "system.heartbeat"
  | "system.budget_exceeded"
  | "system.timeout"
  | "system.agent_crash"
  | "system.config_change"
  | "system.worktree_create";

export type HookPoint = LocalHookPoint | RfcHookPoint;

export interface HookContext {
  point: HookPoint;
  agentId: string;
  data?: any;
}

export interface Hook {
  readonly point: HookPoint;
  readonly priority: number;
  execute(context: HookContext): Promise<void> | void;
}

export type LocalGatePoint =
  | "request:outbound"
  | "response:inbound"
  | "permission"
  | "output"
  | "client-method";

export type RfcGatePoint =
  // Quality Gates
  | "lint"
  | "type_check"
  | "format_check"
  | "build_check"
  | "doc_check"
  | "breaking_change_check"
  // Testing Gates
  | "test"
  | "coverage_threshold"
  // Security Gates
  | "security_scan"
  | "secrets_scan"
  | "dependency_audit"
  | "sast_scan"
  // Review/Council Gates
  | "cross_driver_review"
  // Special Domain Gates (Direction B & C)
  | "experience_schema_validate"
  | "experience_store_verify"
  | "skill_schema_validate"
  | "skill_store_verify"
  | "respawn_cluster_quality"
  | "respawn_experience_assignment"
  | "respawn_registry_update"
  // Council Flow Gates
  | "council_context_validate"
  | "participant_profile_validate"
  | "extraction_schema_validate"
  | "evidence_coverage_check"
  | "proposal_evidence_validate"
  | "review_evidence_validate"
  | "conflict_cluster_validate"
  | "decision_packet_validate"
  | "council_audit_pack_check"
  | "human_approval_wait";

export type GatePoint = LocalGatePoint | RfcGatePoint;

export interface GateContext {
  point: GatePoint;
  agentId: string;
  data: any;
}

/**
 * Gate Decision options.
 * Backward compatible with action: "pass" | "modify" | "block",
 * while aligning with D.1 & D.2: "allow" | "deny" | "ask" | "defer"
 */
export type LocalGateDecision =
  | { action: "pass" }
  | { action: "modify"; value: any }
  | { action: "block"; reason: string };

export type RfcGateDecisionValue = "allow" | "deny" | "ask" | "defer";

export type GateDecision = LocalGateDecision | { action: "rfc"; decision: RfcGateDecisionValue; reason?: string; payload?: any };

export interface Gate {
  readonly point: GatePoint;
  readonly priority: number;
  intercept(context: GateContext): Promise<GateDecision> | GateDecision;
}

/**
 * Direction D.2 Gates RFC Standard Data Structures
 */
export interface GateRequest {
  gate_id: string;
  gate_point: string;
  subject_id: string;
  priority: number;
  denying: boolean;
  timeout_ms: number;
  created_at: string;
  payload?: Record<string, any>;
}

export interface GateResult {
  gate_result_id: string;
  gate_point: string;
  subject_id: string;
  decision: RfcGateDecisionValue;
  reason: string;
  required_actions: string[];
  audit_ref: string;
  target_state?: string;
  created_at: string;
}

export type DriverType = 'acp' | 'pty_fallback' | 'mock';

export type DriverAuthStrategy = 'env-auto' | 'interactive' | 'pre-configured' | 'none';

export interface DriverExecutionInput {
  taskId: string;
  prompt: string;
  sandboxDir?: string;
  environment?: Record<string, string>;
  options?: Record<string, any>;
}

export type DriverErrorCode =
  | 'SPAWN_FAILED'
  | 'AUTH_FAILED'
  | 'EXECUTION_TIMEOUT'
  | 'SANDBOX_VIOLATION'
  | 'ABORTED'
  | 'UNEXPECTED';

export interface DriverErrorState {
  code: DriverErrorCode;
  message: string;
  stack?: string;
}

export interface TranscriptStep {
  timestamp: string;
  type: 'input' | 'thought' | 'tool_call' | 'tool_response' | 'output' | 'stderr';
  payload: any;
}

export interface Transcript {
  sessionId: string;
  steps: TranscriptStep[];
}

export interface ArtifactReference {
  id: string; // Unique Artifact ID
  type: 'patch' | 'file' | 'transcript' | 'diagnostics';
  path: string; // Relative path in sandbox or reference URI
  checksum?: string;
  description?: string;
}

export interface DiagnosticInfo {
  level: 'info' | 'warning' | 'error';
  message: string;
  source: 'agent' | 'client' | 'host' | 'sandbox';
  code?: string;
  details?: any;
}

export interface DriverExecutionResult {
  status: 'success' | 'failed';
  transcript: Transcript;
  artifacts: ArtifactReference[];
  diagnostics: DiagnosticInfo[];
  error?: DriverErrorState;
}

export interface AcpDriver {
  type: DriverType;
  initialize(): Promise<void>;
  execute(input: DriverExecutionInput): Promise<DriverExecutionResult>;
  shutdown(): Promise<void>;
}

import { AcpDriver, DriverExecutionInput, DriverExecutionResult } from "./interface.js";

export class MockDriver implements AcpDriver {
  readonly type = 'mock';
  private initialized = false;

  async initialize(): Promise<void> {
    this.initialized = true;
  }

  async execute(input: DriverExecutionInput): Promise<DriverExecutionResult> {
    if (!this.initialized) {
      throw new Error("Driver not initialized. Please call initialize() first.");
    }

    const isSuccess = !input.prompt.toLowerCase().includes("fail");

    if (isSuccess) {
      return {
        status: 'success',
        transcript: {
          sessionId: `mock-session-${input.taskId}`,
          steps: [
            {
              timestamp: new Date().toISOString(),
              type: 'input',
              payload: input.prompt
            },
            {
              timestamp: new Date().toISOString(),
              type: 'thought',
              payload: "Mock thinking: Analyzing the input codebase pattern. Implementing a secure, modular fix."
            },
            {
              timestamp: new Date().toISOString(),
              type: 'tool_call',
              payload: {
                method: "fs/write_text_file",
                path: "src/driver/mock-driver.ts",
                params: { content: "// mocked changes" }
              }
            },
            {
              timestamp: new Date().toISOString(),
              type: 'output',
              payload: "Task execution successfully completed with mock results."
            }
          ]
        },
        artifacts: [
          {
            id: `art-patch-${input.taskId}`,
            type: 'patch',
            path: 'patches/mock-change.patch',
            description: 'Mocked code patch file representing the task modification.'
          },
          {
            id: `art-transcript-${input.taskId}`,
            type: 'transcript',
            path: 'transcripts/mock-run.json',
            description: 'Mocked step-by-step trace transcript for auditing.'
          }
        ],
        diagnostics: [
          {
            level: 'info',
            message: 'Mock execution completed successfully in virtual sandbox.',
            source: 'sandbox'
          }
        ]
      };
    } else {
      return {
        status: 'failed',
        transcript: {
          sessionId: `mock-session-${input.taskId}`,
          steps: [
            {
              timestamp: new Date().toISOString(),
              type: 'input',
              payload: input.prompt
            },
            {
              timestamp: new Date().toISOString(),
              type: 'thought',
              payload: "Mock thinking: Process failed during compilation stage."
            },
            {
              timestamp: new Date().toISOString(),
              type: 'stderr',
              payload: "Error TS2304: Cannot find name 'UndefinedSymbol'."
            }
          ]
        },
        artifacts: [],
        diagnostics: [
          {
            level: 'error',
            message: "Compilation failed on line 12: Cannot find name 'UndefinedSymbol'.",
            source: 'agent',
            code: 'TS2304'
          }
        ],
        error: {
          code: 'UNEXPECTED',
          message: 'Mock execution simulated a failure as requested by the test prompt.'
        }
      };
    }
  }

  async shutdown(): Promise<void> {
    this.initialized = false;
  }
}

