import { MockDriver, DriverExecutionInput } from "../src/index.js";

async function runTests() {
  console.log("==================================================");
  console.log("Testing MockDriver & RFC Contracts...");
  console.log("==================================================");

  const driver = new MockDriver();

  // 1. Test uninitialized execute throws error
  try {
    await driver.execute({ taskId: "1", prompt: "Hello" });
    console.error("FAIL: Executing uninitialized driver should have thrown an error!");
    process.exit(1);
  } catch (err: any) {
    console.log("SUCCESS: Uninitialized execute correctly threw error:", err.message);
  }

  // 2. Initialize
  await driver.initialize();
  console.log("SUCCESS: Driver initialized successfully.");

  // 3. Test SUCCESS execution
  const successInput: DriverExecutionInput = {
    taskId: "task-001",
    prompt: "Implement a secure endpoint for user authentication."
  };

  const successResult = await driver.execute(successInput);
  console.log("\nSuccess execution result status:", successResult.status);
  if (successResult.status === 'success') {
    console.log("SUCCESS: Received success status.");
    console.log(`SUCCESS: Created ${successResult.artifacts.length} artifacts.`);
    successResult.artifacts.forEach(art => {
      console.log(`   Artifact ID: ${art.id}, Type: ${art.type}, Path: ${art.path}`);
    });
    console.log(`SUCCESS: Created ${successResult.diagnostics.length} diagnostics.`);
    successResult.diagnostics.forEach(diag => {
      console.log(`   Diagnostic [${diag.level}] (${diag.source}): ${diag.message}`);
    });
  } else {
    console.error("FAIL: Expected success execution status but got failed.");
    process.exit(1);
  }

  // 4. Test FAILED execution
  const failInput: DriverExecutionInput = {
    taskId: "task-002",
    prompt: "Run compiling command. Should fail."
  };

  const failResult = await driver.execute(failInput);
  console.log("\nFailed execution result status:", failResult.status);
  if (failResult.status === 'failed') {
    console.log("SUCCESS: Received failed status.");
    console.log(`SUCCESS: Diagnostics length: ${failResult.diagnostics.length}`);
    failResult.diagnostics.forEach(diag => {
      console.log(`   Diagnostic [${diag.level}] (${diag.source}): ${diag.message}`);
    });
    console.log(`SUCCESS: Error state: ${JSON.stringify(failResult.error)}`);
  } else {
    console.error("FAIL: Expected failed execution status but got success.");
    process.exit(1);
  }

  // 5. Shutdown
  await driver.shutdown();
  console.log("\nSUCCESS: Driver shut down successfully.");
  console.log("==================================================");
  console.log("All MockDriver tests passed successfully!");
  console.log("==================================================");
}

runTests().catch(err => {
  console.error("Test execution failed:", err);
  process.exit(1);
});

