export class InMemoryArtifactStore {
  private readonly artifacts = new Map<ArtifactId, ArtifactRef>();

  register(artifact: ArtifactRef): ArtifactRef {
    this.artifacts.set(artifact.artifact_id, artifact);
    return artifact;
  }

