export type HookPoint =
  // ACP Client Lifecycle Hooks
  | "pre:connect"
  | "post:connect"
  | "pre:initialize"
  | "post:initialize"
  | "pre:authenticate"
  | "post:authenticate"
  | "pre:session:create"
  | "post:session:create"
  | "pre:prompt"
  | "post:prompt"
  | "pre:disconnect"
  | "post:disconnect"
  // Driver / Agent Runtime Hooks
  | "agent.pre_tool_use"
  | "agent.post_tool_use"
  | "agent.post_tool_use_fail"
  | "agent.checkpoint"
  | "agent.session_start"
  | "agent.session_end"
  | "lifecycle.human_gate";

export interface HookContext {
  point: HookPoint;
  agentId: string;
  data?: any;
}

export interface Hook {
  readonly point: HookPoint;
  readonly priority: number;
  execute(context: HookContext): Promise<void> | void;
}

export type GatePoint =
  | "request:outbound"
  | "response:inbound"
  | "permission"
  | "output"
  | "client-method"
  // Driver / Agent Runtime Gates
  | "lint"
  | "type_check"
  | "format_check"
  | "build_check"
  | "test"
  | "security_scan"
  | "human_approval_wait";

export interface GateContext {
  point: GatePoint;
  agentId: string;
  data: any;
}

export type GateDecision =
  | { action: "pass" }
  | { action: "modify"; value: any }
  | { action: "block"; reason: string }
  | { action: "rfc"; decision: "allow" | "deny" | "ask" | "defer"; reason?: string; payload?: any };

export interface Gate {
  readonly point: GatePoint;
  readonly priority: number;
  intercept(context: GateContext): Promise<GateDecision> | GateDecision;
}

export interface GateRequest {
  gate_id: string;
  gate_point: string;
  subject_id: string;
  priority: number;
  denying: boolean;
  timeout_ms: number;
  created_at: string;
  payload?: Record<string, any>;
}

export interface GateResult {
  gate_result_id: string;
  gate_point: string;
  subject_id: string;
  decision: "allow" | "deny" | "ask" | "defer";
  reason: string;
  required_actions: string[];
  audit_ref: string;
  target_state?: string;
  created_at: string;
}

import {
  Hook,
  Gate,
  HookPoint,
  GatePoint,
  HookContext,
  GateContext,
  GateDecision,
} from "./interface.js";

export class HookRegistry {
  private hooks = new Map<HookPoint, Hook[]>();

  register(hook: Hook) {
    const list = this.hooks.get(hook.point) || [];
    list.push(hook);
    list.sort((a, b) => a.priority - b.priority);
    this.hooks.set(hook.point, list);
  }

  async execute(point: HookPoint, context: HookContext): Promise<void> {
    const list = this.hooks.get(point) || [];
    for (const hook of list) {
      await hook.execute(context);
    }
  }
}

export class GateRegistry {
  private gates = new Map<GatePoint, Gate[]>();

  register(gate: Gate) {
    const list = this.gates.get(gate.point) || [];
    list.push(gate);
    list.sort((a, b) => a.priority - b.priority);
    this.gates.set(gate.point, list);
  }

  async intercept(point: GatePoint, context: GateContext): Promise<GateDecision> {
    const list = this.gates.get(point) || [];
    let currentDecision: GateDecision = { action: "pass" };

    for (const gate of list) {
      const decision = await gate.intercept({ ...context, data: currentDecision.action === "modify" ? currentDecision.value : context.data });
      if (decision.action === "block") return decision;
      if (decision.action === "modify") {
        currentDecision = decision;
      }
    }
    return currentDecision;
  }
}

不，**目前的实现依然存在明显的职责混淆，并不符合我们刚才厘清的“纯 Event Publisher + Unary Interceptor”职责划分。**

如果仔细审视现有的 `@src/hook-gate/` 与 `AcpClient` 的交互，我们会发现以下几个核心设计冲突：

---

### 1. 核心冲突一：Client 依然是 Hook/Gate 的“执行宿主” (Coupling)
在现有的 `AcpClient` 中：
* `AcpClientOptions` 依然强行要求传入 `hookRegistry` 和 `gateRegistry`。
* 在生命周期的每个时点，Client 依然在**主动调用并等待**：
  ```typescript
  await this.hookRegistry.execute("pre:connect", { point: "pre:connect", agentId });
  ```
这说明 Client 依然在自己内部“默默消化” Hook 逻辑。如果 Hook 的执行逻辑挂起或崩溃，Client 将连带崩溃。这不符合 **“Client 仅抛出事件，不参与策略计算”** 的解耦要求。

---

### 2. 核心冲突二：`src/hook-gate/registry.ts` 存在于当前包内 (Wrong Domain)
在多方向分工中，`HookRegistry`（D.1 钩子注册）与 `GateRegistry`（D.2 门禁拦截注册）应该属于 **Direction D 独立治理域**。
* 当前包 `acp-client-prototype` 强行声明并导出了这两个 Registry。
* 只要这两个类属于本项目，大项目在接入时，就会倾向于直接在 `AcpClient` 层把各种 Gate（如编译检查、安全扫描）注册进来，从而污染了 Direction A（运行时驱动）的无状态性。

---

### 3. 符合“纯 Event Publisher + Unary Interceptor”的重构设想

为了完美划清职责，当您同意进行重构时，我们应该采取以下**去 Registry 化**的极致解耦设计：

#### 3.1 Hook 部分：彻底退化为 Standard Event EventEmitter
我们不应该在 Client 里执行任何 Hook，Client 只管 `emit`：
1. **定义 Client 支持抛出的标准事件类型**：
   ```typescript
   export type ClientEvents = {
     "pre:connect": (payload: { agentId: string }) => void;
     "post:connect": (payload: { agentId: string }) => void;
     "agent.checkpoint": (payload: { agentId: string; checkpoint: any }) => void;
     // ... 其他 ACP 级事件
   };
   ```
2. **Client 内部实现**：
   ```typescript
   // 纯 EventEmitter，无任何 hookRegistry 的导入与执行
   this.emit("pre:connect", { agentId });
   ```
3. **上层 (Coordinator) 的消费方式**：
   上层长程协调器在初始化时，监听 Client 的事件，并将其转发给 **Direction D 的 HookEngine**：
   ```typescript
   client.on("agent.checkpoint", (payload) => {
     hookEngine.handleEvent({ event_type: "agent.checkpoint", payload });
   });
   ```

#### 3.2 Gate 部分：退化为单体拦截回调 (Unary Callback)
针对必须在 Client 运行时同步拦截、并返回修改后数据或阻断决策的 Gate 点位（如用户交互确认），Client 不应该内置 `GateRegistry` 进行多级决策计算，而是定义一个**一级 Callback 回调挂载句柄**：

```typescript
export class AcpClient extends EventEmitter {
  // 定义一个选填的一级拦截器，用于询问外部（宿主安全决策网关）
  private permissionInterceptor?: (request: PermissionRequest) => Promise<boolean>;

  setPermissionInterceptor(interceptor: (request: PermissionRequest) => Promise<boolean>) {
    this.permissionInterceptor = interceptor;
  }

  // 内部调用
  private async askPermission(req: PermissionRequest): Promise<boolean> {
    if (this.permissionInterceptor) {
      // 询问外部是否允许
      return await this.permissionInterceptor(req);
    }
    return true; // 默认放行
  }
}
```
此时，Client 将“门禁判断”和“优先级聚合决策”的全部复杂度剥离。大项目接入时：
* 协调层或 D 方向的 `GateRegistry` 负责决定 `lint > test` 的聚合结果。
* 外部计算出最终结果后，单线返回给 Client 一个 `true` 或 `false`，Client 只需要据此执行“通过”或“阻断”动作。

---

### 💬 讨论

如果我们按照上述模型，将 `acp-client-prototype` 库改造为：
1. 彻底删除 `src/hook-gate/registry.ts`，不再向外提供任何 Hook/Gate 的注册表；
2. 让 `AcpClient` 变为一个单纯的 `EventEmitter`，彻底告别构造函数中对 `hookRegistry` 和 `gateRegistry` 的强依赖；
3. 将不得不同步拦截的权限、安全点位改造成 Unary Callback 接口。

这样，我们的项目不仅对 Direction A 实现了高度纯粹的抽象，更能实现与大项目（`newIDE-BCD`）在 D.1 / D.2 方向上的完美对接。

您认可这样的演进路线吗？如果认可，请发出指令，我们将对代码和 SPEC 进行同步调整。

