export type HookPoint =
  // ACP Client Lifecycle Hooks
  | "pre:connect"
  | "post:connect"
  | "pre:initialize"
  | "post:initialize"
  | "pre:authenticate"
  | "post:authenticate"
  | "pre:session:create"
  | "post:session:create"
  | "pre:prompt"
  | "post:prompt"
  | "pre:disconnect"
  | "post:disconnect"
  // Driver / Agent Runtime Hooks
  | "agent.pre_tool_use"
  | "agent.post_tool_use"
  | "agent.post_tool_use_fail"
  | "agent.checkpoint"
  | "agent.session_start"
  | "agent.session_end"
  | "lifecycle.human_gate";

export interface HookContext {
  point: HookPoint;
  agentId: string;
  data?: any;
}

export type GatePoint =
  | "request:outbound"
  | "response:inbound"
  | "permission"
  | "output"
  | "client-method"
  // Driver / Agent Runtime Gates
  | "lint"
  | "type_check"
  | "format_check"
  | "build_check"
  | "test"
  | "security_scan"
  | "human_approval_wait";

/**
 * Pure Interceptors interface for ACP Client/Driver.
 * The Client does not hold Registries, and instead exposes these
 * direct, unary callbacks to delegate decision-making to the external Policy Engine.
 */
export interface ClientInterceptors {
  output?: (event: any) => Promise<any | null> | any | null;
  permission?: (request: any) => Promise<boolean> | boolean;
}

export interface GateRequest {
  gate_id: string;
  gate_point: string;
  subject_id: string;
  priority: number;
  denying: boolean;
  timeout_ms: number;
  created_at: string;
  payload?: Record<string, any>;
}

export interface GateResult {
  gate_result_id: string;
  gate_point: string;
  subject_id: string;
  decision: "allow" | "deny" | "ask" | "defer";
  reason: string;
  required_actions: string[];
  audit_ref: string;
  target_state?: string;
  created_at: string;
}

这是一个非常敏锐且直击软件工程本质的质问。

如果您要求的是**绝对、彻底的解耦（Absolute Decoupling）**，那么您的直觉是 100% 正确的：**`acp-client-prototype` 作为一个纯粹的 Direction A (Client/Driver) 包，其源码目录中根本不应该存在 `src/hook-gate/` 文件夹，更不应该去定义 `HookPoint`、`GatePoint`、`GateRequest` 和 `GateResult` 这些接口。**

目前我们在 `src/hook-gate/interface.ts` 中保留这些接口，确实带有明显的“原型阶段的妥协与过渡期考量”。以下是我们的深度考量与技术推演：

---

### 一、 为什么目前保留了这些定义？（过渡期考量）

在开发生命周期中，我们面临着一个典型的**多方向并发开发（Concurrent Phase）矛盾**：
1. **大项目联合调试的需要（Bridge / Shim）**：
   在您提供的大项目（Scaffold Clone）尚未完成多包（Monorepo）抽离并发布 `@newide/core` 之前，本项目作为独立的库，需要向大项目的检查者**单向证明**：*“我是有能力抛出完全符合 D.1/D.2 规范的事件的，并且我的拦截定义在类型系统上是契合 4 级决策的。”*
2. **测试层（`driver.test.ts`）的独立闭环**：
   如果彻底把 `src/hook-gate` 扬掉，由于目前我们的单体库缺乏上层 Coordinator 和 Gate Runner 的实机环境，测试层（如验证 MockDriver 产出 Diagnostic 的行为）会失去强类型的接口对照。

因此，当前在 `src/hook-gate/interface.ts` 中定义的接口，更像是一个**“跨方向对齐的类型垫片（Type Shim）”**。

---

### 二、 如果实现“极致、彻底的解耦”，架构应该长什么样？

如果我们按照 `newide-scaffold-clone` 的标准，彻底把 Direction A（运行时）与 Direction D（策略门禁）从物理上剥离，我们应当做以下**彻底的物理消融（Zero-Leakage Architecture）**：

#### 1. 彻底删除 `src/hook-gate/` 文件夹
Direction A 包内不再包含任何 Hook、Gate 相关的概念，也没有 `HookPoint` 和 `GatePoint` 字符联合体。

#### 2. Client 只定义自己的 Local EventEmitter 契约
在 `src/client/acp-client.ts` 内部，Client 仅根据自己的**物理通信步骤**声明自己的 EventEmitter 类型。它完全不知道有 D.1 事件命名空间（`agent.*`, `task.*`）这回事：
```typescript
// 纯粹、无策略侵入的 Client 物理时点事件
export type AcpClientEvents = {
  "connect:before": (payload: { agentId: string }) => void;
  "connect:after": (payload: { agentId: string }) => void;
  "initialize:after": (payload: { result: InitializeResult }) => void;
  "prompt:before": (payload: { prompt: string }) => void;
  "prompt:chunk": (payload: { text: string }) => void;
  "prompt:after": (payload: { durationMs: number }) => void;
  "error": (err: Error) => void;
};
```

#### 3. Client 只声明极窄的 Unary Interceptor
Client 不导入任何 D.2 级的 `GateRequest` 或 `GateResult`，仅在 [src/client/acp-client.ts](src/client/acp-client.ts) 内部声明两个用于同步挂起的局部回调，参数采用最通用的 raw 类型或连接层类型：
```typescript
export interface ClientInterceptors {
  // 仅传入 ConnectionEvent 报文，由外部清洗后返回，或者返回 null 以强行丢弃
  output?: (event: ConnectionEvent) => Promise<ConnectionEvent | null> | ConnectionEvent | null;
  // 仅传入具体工具请求，由外部判定是否授权执行
  permission?: (request: { method: string; params: any }) => Promise<boolean> | boolean;
}
```

#### 4. 依赖倒置：大项目（Coordinator / Engine）负责翻译与拼装
当上层系统（如 Scaffold）加载我们的包时，由 **Direction D 的 HookEngine** 充当适配器（Adapter），在外部去监听 Client 抛出的物理事件，并将其“翻译并升级”为 5 大命名空间的策略事件：
```typescript
import { AcpClient } from "acp-client-prototype";
import { hookEngine } from "@/hook-engine"; // 属于大项目

// 在外层进行适配和路由：将 Client 的 "connect:after" 翻译成 D.1 的 "agent.session_start"
client.on("connect:after", (payload) => {
  hookEngine.handleEvent({
    event_type: "agent.session_start",
    subject_id: payload.agentId,
    payload: { timestamp: new Date().toISOString() }
  });
});
```

同时，外层协调器将 `GateRegistry` 算出的最终判定以简易回调的形式喂给 Client：
```typescript
client.setPermissionInterceptor(async (req) => {
  // 外部 Gate 引擎运行真实的 lint/test/security 复杂管道检测
  const gateResult = await gateRegistry.evaluate("permission", req);
  return gateResult.decision === "allow"; // 单线返回 boolean
});
```

---

### 💬 结论与您的抉择

* **目前的做法**：属于**“契约可见、逻辑解耦”**。Client 不执行拦截逻辑，但 Client 知道 D.1/D.2 的点位名称，充当类型垫片。
* **彻底的做法**：属于**“契约也完全不可见、彻底的物理消融”**。Client 连 Hook/Gate 两个词长什么样都不知道，只抛出局部的、纯物理的 `connect:before`，把命名翻译和决策聚合全部推给大项目。

如果您更倾向于第二种**极致无感知、无泄露的真解耦**，我随时可以为您将 `src/hook-gate/` 物理扬掉，并把 Client 纯化至没有任何策略依赖的状态。

我想听听您从团队协作和大项目架构管控角度出发的意见：**我们是要保留这层“契约垫片”，还是直接一步到位，执行彻底的物理消融？**

import type {
  ArtifactRef,
  ContextPackRef,
  DriverId,
  DriverSessionId,
  RunId,
  SchemaVersion,
  TaskId,
  Timestamp
} from "../core";

export interface DriverCapabilities {
  supports_acp_extension: boolean;
  supports_structured_output: boolean;
  supports_session_load: boolean;
  supports_tool_events: boolean;
  supports_permission_events: boolean;
}

export interface DriverPrompt {
  task_id: TaskId;
  run_id: RunId;
  prompt: string;
  context_pack_ref?: ContextPackRef;
  created_at: Timestamp;
  schema_version: SchemaVersion;
}

export interface DriverToolEvent {
  tool_event_id: string;
  tool_name: string;
  status: "pending" | "in_progress" | "completed" | "failed";
  summary: string;
  created_at: Timestamp;
  schema_version: SchemaVersion;
}

export interface DriverError {
  code: string;
  message: string;
  retryable: boolean;
}

export type DriverRunStatus = "succeeded" | "failed" | "cancelled" | "interrupted";

export interface DriverRunResult {
  driver_run_result_id: string;
  session_id: DriverSessionId;
  status: DriverRunStatus;
  artifacts: ArtifactRef[];
  transcript_ref: ArtifactRef;
  tool_events: DriverToolEvent[];
  diagnostics: {
    driver_id: DriverId;
    duration_ms: number;
    notes: string[];
  };
  error?: DriverError;
  created_at: Timestamp;
  schema_version: SchemaVersion;
}

export interface DriverRuntimeHandle {
  driver_id: DriverId;
  session_id: DriverSessionId;
  capabilities: DriverCapabilities;
  sendPrompt(input: DriverPrompt): Promise<DriverRunResult>;
  interrupt(reason: string): Promise<void>;
  collectTranscript(): Promise<ArtifactRef>;
}

这是一次极具穿透力的架构审视。如果我们把目前的 `AcpClient` 与 `@newide-scaffold-clone` 中定义的 `DriverRuntimeHandle` 进行直接对照，答案是：

**不符合。现在的 `AcpClient` 并不是 `@newide-scaffold-clone` 中所期待的 “Driver” 包装器。**

它们代表了两个完全不同的**职责抽象层级**：一个属于 **Micro-Level (微观协议通道)**，另一个属于 **Macro-Level (宏观任务执行 envelope)**。

以下是我们的职责讨论与全景推演：

---

### 一、 两个层级的核心落差（Micro-Level vs Macro-Level）

| 维度 | `AcpClient` (微观协议客户端) | `DriverRuntimeHandle` (宏观执行驱动) |
| :--- | :--- | :--- |
| **工作流定位** | **数据通道流**。它维持进程、编排 JSON-RPC 报文。 | **任务生命周期执行器**。它对 C 方向（协调器）负责，完成单次 prompt 的吞吐闭环。 |
| **`sendPrompt` 的返回契约** | **流式迭代器 (TurnController / Stream Iterator)**。提供流式的 `thought`、`message_chunk`、`tool_call` 事件。 | **完全解析的块包 (Promise<DriverRunResult>)**。一次性交付运行完成后的成果信封，不流式返回。 |
| **产物交付时机** | 在运行期间流式触发 `tool_call`（如 fs 写入文件），**不负责最终产物和审计追踪的打包**。 | 在运行结束后，将本次运行产生的 Patch 补丁、会话 Transcript 汇总为可寻址资产，并进行关系化登记。 |

也就是说：
* `AcpClient` 类似于一个 **Database Driver (数据库连接驱动)**：它负责向数据库发送查询，拿到的是一个 `Cursor`（游标）或字节流。
* `DriverRuntimeHandle` 类似于一个 **Repository/Transaction Manager (事务或服务执行器)**：它接单、执行、记录事务状态，最终返回一个“订单执行结果”信封。

---

### 二、 真实的 `AcpDriver` 应该如何包装 `AcpClient`？

在脚手架生产环境中，`AcpClient` 不直接面向控制面（Coordinator）。应当由一个 **`AcpDriver`（属于 Direction A）** 去实例化并包裹 `AcpClient`，实现 `DriverRuntimeHandle` 的契约：

```
┌────────────────────────────────────────────────────────┐
│               Coordinator / C Direction                │
└───────────────────────────┬────────────────────────────┘
                            │ execute(DriverPrompt)
                            ▼
┌────────────────────────────────────────────────────────┐
│                AcpDriver (Direction A)                 │
│                                                        │
│   1. 实例化并管理 AcpClient 物理实例                   │
│   2. 订阅 Client 的流式事件进行汇总 (Accumulate)        │
│   3. 监听并拦截 tool_call，映射为 DriverToolEvent      │
│   4. 将通信日志汇总为 Transcript Artifact              │
└───────────────────────────┬────────────────────────────┘
                            │ sendPrompt(string)
                            ▼
┌────────────────────────────────────────────────────────┐
│               AcpClient (Direction A Core)             │
│                                                        │
│   1. 通信、协议握手与 StdIO 流式序列化                 │
└────────────────────────────────────────────────────────┘
```

#### 2.1 真实的 `sendPrompt` 包装与积聚流程：
当控制面（Coordinator）向 `AcpDriver` 提交 `sendPrompt(DriverPrompt)` 时，`AcpDriver` 内部进行如下流式积聚（Accumulation）：

```typescript
export class RealAcpDriver implements DriverRuntimeHandle {
  readonly driver_id = "real-acp-driver";
  readonly session_id = "acp-session-001";
  private client: AcpClient; // 持有微观客户端

  constructor(client: AcpClient) {
    this.client = client;
  }

  async sendPrompt(input: DriverPrompt): Promise<DriverRunResult> {
    const startTime = Date.now();
    const toolEvents: DriverToolEvent[] = [];

    // 1. 初始化并建立会话
    await this.client.initialize();
    await this.client.createSession(process.cwd()); // Sandbox 

    // 2. 发送 Prompt 并获取微观流游标
    const turn = await this.client.sendPrompt(input.prompt);

    // 3. 微观流的消费与积聚 (Accumulate chunks)
    for await (const chunk of turn) {
      if (chunk.type === "tool_call") {
        // 记录工具执行事件
        toolEvents.push({
          tool_event_id: chunk.payload.callId,
          tool_name: chunk.payload.method,
          status: "completed",
          summary: `Executed tool: ${chunk.payload.method}`,
          created_at: new Date().toISOString(),
          schema_version: "v0"
        });
      }
      // 可以在此处打印流式 thought 或 message_chunk 到宿主终端
    }

    // 4. 等待执行结果，构建最终信封
    const resultStatus = turn.result === "success" ? "succeeded" : "failed";

    // 5. 汇总本次执行产生的文件与 Transcript，转为 Artifact 资产
    const transcriptRef: ArtifactRef = await this.collectTranscript(input.task_id);
    const patchArtifact: ArtifactRef = {
      artifact_id: "art_patch_001",
      type: "patch",
      uri: `artifact://patch/${input.task_id}/driver.patch`,
      producer_id: this.driver_id,
      created_at: new Date().toISOString(),
      schema_version: "v0"
    };

    return {
      driver_run_result_id: "run_res_001",
      session_id: this.session_id,
      status: resultStatus,
      artifacts: [patchArtifact],
      transcript_ref: transcriptRef,
      tool_events: toolEvents,
      diagnostics: {
        driver_id: this.driver_id,
        duration_ms: Date.now() - startTime,
        notes: ["Real ACP session processed successfully."]
      },
      created_at: new Date().toISOString(),
      schema_version: "v0"
    };
  }

  async interrupt(reason: string): Promise<void> {
    await this.client.shutdown();
  }

  async collectTranscript(taskId: string): Promise<ArtifactRef> {
    // 将 client 积累的 session history 转存为可寻址 JSON 产物
    return {
      artifact_id: "art_trans_001",
      type: "transcript",
      uri: `artifact://transcript/${taskId}/acp-session`,
      producer_id: this.driver_id,
      created_at: new Date().toISOString(),
      schema_version: "v0"
    };
  }
}
```

---

### 三、 我们的考量与设计方向

1. **Client 不应该与 `DriverPrompt`/`DriverRunResult` 产生任何直接耦合**。因为 Client 代表的是纯物理的 ACP 通信，如果强行把 `schema_version`、`task_id`、`run_id` 等高阶 C 方向属性引入 Client，就会极大降低底层驱动通信层的通用性。
2. **需要一个 `RealAcpDriver` 作为粘合层（Glue Layer）**。它左手调用 `AcpClient` 读写网络流，右手向 C 方向协调层输出结构化的 `DriverRunResult` 信封。

您认可这样的物理分层设计吗？如果认可，我们接下来在 SPEC 的 **“第 6 章 能力拆分与第一阶段接入矩阵”** 中补充这一段“微观 Client 经由包装，交付宏观 Driver 契约”的设计，彻底划清大项目下的全景对接职责。

