## 3. 方向 A：Driver 接入层契约 Spec 定义

方向 A 的主要目标是定义统一的驱动执行标准。所有 Driver 必须遵循 `AcpDriver` 契约，将输入转化为携带 Transcript、Artifacts 和 Diagnostics 的结构化执行结果。

### 3.1 核心 TypeScript 类型定义 (`src/driver/interface.ts`)

```typescript
export type DriverType = 'acp' | 'pty_fallback' | 'mock';

export type DriverAuthStrategy = 'env-auto' | 'interactive' | 'pre-configured' | 'none';

/**
 * Driver 执行输入：由 C 方向（长程协调器）分派给驱动
 */
export interface DriverExecutionInput {
  taskId: string;                    // 任务 ID
  prompt: string;                    // 执行指令 / User Prompt
  sandboxDir?: string;               // 强制路径沙箱目录
  environment?: Record<string, string>; // 环境变量覆盖
  options?: Record<string, any>;     // 扩展配置
}

/**
 * 驱动运行期错误状态码
 */
export type DriverErrorCode =
  | 'SPAWN_FAILED'         // 子进程拉起失败
  | 'AUTH_FAILED'          // 认证凭证解析失败
  | 'EXECUTION_TIMEOUT'    // 执行超时
  | 'SANDBOX_VIOLATION'    // 沙箱越界读写
  | 'ABORTED'              // 任务被中途取消
  | 'UNEXPECTED';          // 未捕获的内部异常

export interface DriverErrorState {
  code: DriverErrorCode;
  message: string;
  stack?: string;
}

/**
 * Transcript 步骤：流式记录执行驱动的思维与操作链路
 */
export interface TranscriptStep {
  timestamp: string;
  type: 'input' | 'thought' | 'tool_call' | 'tool_response' | 'output' | 'stderr';
  payload: any; // 携带的具体消息或参数
}

export interface Transcript {
  sessionId: string;
  steps: TranscriptStep[];
}

/**
 * 产物引用：支持 C 方向（长程协调器）寻址和注册
 */
export interface ArtifactReference {
  id: string;                         // 产物全局唯一标识
  type: 'patch' | 'file' | 'transcript' | 'diagnostics'; // 产物类型
  path: string;                       // 可寻址 URI (格式：artifact://...) 或相对沙箱的路径
  checksum?: string;                  // SHA-256 校验和
  description?: string;               // 产物说明
}

/**
 * 诊断信息
 */
export interface DiagnosticInfo {
  level: 'info' | 'warning' | 'error';
  message: string;
  source: 'agent' | 'client' | 'host' | 'sandbox';
  code?: string;                      // 编译器/Lint 错误码
  details?: any;
}

/**
 * Driver 执行结果：向 C 方向交付的标准结果信封
 */
export interface DriverExecutionResult {
  status: 'success' | 'failed';
  transcript: Transcript;
  artifacts: ArtifactReference[];
  diagnostics: DiagnosticInfo[];
  error?: DriverErrorState;
}

/**
 * 外部 Driver 统一契约
 */
export interface AcpDriver {
  type: DriverType;
  initialize(): Promise<void>;
  execute(input: DriverExecutionInput): Promise<DriverExecutionResult>;
  shutdown(): Promise<void>;
}
```

